{"command": "cd ~/ctf_files/attachment && cat > /tmp/solve.py <<'EOF'
import zipfile, struct, collections, hashlib
z=zipfile.ZipFile('/home/ctf_files/attachment/maze.pt')
vals=struct.unpack('<1764f', z.read('archive/data/0'))
N=42
G=[list(vals[i*N:(i+1)*N]) for i in range(N)]

def bfs(grid):
    start=end=None
    for i in range(N):
        for j in range(N):
            if grid[i][j]==2.0: start=(i,j)
            if grid[i][j]==3.0: end=(i,j)
    dirs={'W':(-1,0),'S':(1,0),'A':(0,-1),'D':(0,1)}
    prev={}; q=collections.deque([start]); seen={start}
    while q:
        cur=q.popleft()
        if cur==end: break
        for k,(di,dj) in dirs.items():
            n=(cur[0]+di,cur[1]+dj)
            if 0<=n[0]<N and 0<=n[1]<N and grid[n[0]][n[1]]!=1.0 and n not in seen:
                seen.add(n); prev[n]=(cur,k); q.append(n)
    path=[]; cur=end
    while cur!=start:
        p,k=prev[cur]; path.append(k); cur=p
    return start,end,''.join(reversed(path))

def is_tree(grid):
    cells=[(i,j) for i in range(N) for j in range(N) if grid[i][j]!=1.0]
    idx={c:i for i,c in enumerate(cells)}
    par=list(range(len(cells)))
    def f(x):
        while par[x]!=x:
            par[x]=par[par[x]]; x=par[x]
        return x
    edges=0
    comps=set()
    for i,j in cells:
        for di,dj in ((1,0),(0,1)):
            n=(i+di,j+dj)
            if n in idx:
                edges+=1
                a,b=f(idx[(i,j)]),f(idx[n])
                if a!=b: par[a]=b
    for c in cells: comps.add(f(idx[c]))
    print('cells',len(cells),'edges',edges,'components',len(comps),'tree' if edges==len(cells)-1 and len(comps)==1 else 'CYCLIC')

is_tree(G)
T=[list(r) for r in zip(*G)]
is_tree(T)

for name,g in [('normal',G),('transposed',T)]:
    s,e,p=bfs(g)
    print(name, s,e,len(p))
    print(p)
    print('md5 upper', hashlib.md5(p.encode()).hexdigest())
    print('md5 lower', hashlib.md5(p.lower().encode()).hexdigest())
